function RichText({name,placeholder}:{name:string;placeholder:string}){const [html,setHtml]=useState('');function command(cmd:string){document.execCommand(cmd);const el=document.getElementById(`editor-${name}`);if(el)setHtml(el.innerHTML)}return <div className="rich-editor"><div className="rich-toolbar"><button type="button" onClick={()=>command('bold')}><b>B</b></button><button type="button" onClick={()=>command('italic')}><i>I</i></button><button type="button" onClick={()=>command('insertUnorderedList')}>• List</button><button type="button" onClick={()=>command('formatBlock')} >H</button></div><div id={`editor-${name}`} contentEditable suppressContentEditableWarning onInput={e=>setHtml(e.currentTarget.innerHTML)} data-placeholder={placeholder}/><input type="hidden" name={name} value={html}/></div>}

